<div class="card"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">Products</h2><button type="button" id="add-item" class="btn btn-sm btn-outline-primary">Add row</button></div><table class="table"><thead><tr><th>Product</th><th style="width:220px">{{ $signed?'Quantity change':'Quantity' }}</th><th style="width:60px"></th></tr></thead><tbody id="item-rows"></tbody></table></div></div>@push('scripts')<script>let inventoryRow=0;const inventoryProducts=@json($products->map(fn($p)=>['id'=>$p->id,'name'=>$p->item_code+' — '+$p->name,'qty'=>$p->current_quantity]));function addInventoryRow(){const i=inventoryRow++;document.getElementById('item-rows').insertAdjacentHTML('beforeend',`<tr><td><select name="items[${i}][product_id]" class="form-select" required><option value="">Select product</option>${inventoryProducts.map(p=>`<option value="${p.id}">${p.name} (company ${p.qty})</option>`).join('')}</select></td><td><input type="number" step="0.0001" {{ $signed?'':'min="0"' }} name="items[${i}][{{ $field }}]" class="form-control" value="0"></td><td><button type="button" class="btn btn-outline-danger" onclick="this.closest('tr').remove()"><i class="bi bi-trash"></i></button></td></tr>`)}document.getElementById('add-item').onclick=addInventoryRow;addInventoryRow();</script>@endpush
